package ru.folio.notes;

import java.util.*;

public final class CanvasTests {
    static int assertions;static Random random=new Random(1500);
    static void check(boolean yes,String label){if(!yes)throw new AssertionError(label);assertions++;}
    static Ink.Stroke line(float x,float y,float x2,float y2){Ink.Stroke s=new Ink.Stroke();s.points.add(new Ink.Pt(x,y,1,0,0));s.points.add(new Ink.Pt(x2,y2,1,0,0));return s;}
    static void index(){SpatialIndex index=new SpatialIndex();ArrayList<Ink.Stroke> strokes=new ArrayList<>();for(int i=0;i<2500;i++){float x=(random.nextFloat()-.5f)*40000,y=(random.nextFloat()-.5f)*40000;Ink.Stroke s=line(x,y,x+random.nextFloat()*300,y+random.nextFloat()*300);strokes.add(s);index.add(s,i);}Ink.Stroke huge=line(-800000,-200,800000,200);strokes.add(huge);index.add(huge,2500);check(index.large.contains(huge)&&index.cells.size()<12000,"very large stroke does not populate the whole world");
        for(int q=0;q<700;q++){float l=(random.nextFloat()-.5f)*41000,t=(random.nextFloat()-.5f)*41000,r=l+1200,b=t+900;ArrayList<Ink.Stroke> found=index.query(l,t,r,b),expected=new ArrayList<>();for(Ink.Stroke s:strokes)if(CanvasViewport.overlaps(s.bounds(),l,t,r,b))expected.add(s);check(found.equals(expected),"spatial candidates and stacking equal brute-force world bounds");}
        Ink.Stroke negative=line(-30000,-40000,-29800,-39800);index.add(negative,-1);check(index.query(-30100,-40100,-29700,-39700).get(0)==negative,"negative world lookup and stacking");index.remove(negative);check(!index.query(-30100,-40100,-29700,-39700).contains(negative),"removed negative stroke leaves no stale candidates");Ink.Stroke clipped=huge.cut(100,0,20);index.remove(huge);index.add(clipped,2500);check(index.query(-10,-10,110,10).contains(clipped)&&!index.query(-10,-10,110,10).contains(huge),"eraser copy replaces large-stroke identity");check(index.query(-1000000,-1000000,1000000,1000000).size()==2501,"large overview queries use bounded cell work");index.add(new Ink.Stroke(),2600);check(index.entries.size()==2501,"empty imported marks cannot pollute index");index.clear();check(index.entries.isEmpty()&&index.cells.isEmpty()&&index.large.isEmpty(),"index cleanup");System.out.println("PASS sparse negative/positive world index, stacking, broad-phase reference, huge strokes, erase replacement and cleanup");}
    static void viewport(){for(int i=0;i<3000;i++){float fit=.5f+random.nextFloat()*3,zoom=.08f+random.nextFloat()*11,next=.08f+random.nextFloat()*11,tx=(random.nextFloat()-.5f)*10000,ty=(random.nextFloat()-.5f)*10000,ax=random.nextFloat()*2000,ay=random.nextFloat()*1400,bx=ax+100,by=ay-75;float wx=(ax-tx)/(fit*zoom),wy=(ay-ty)/(fit*zoom);float[] p=CanvasViewport.zoom(tx,ty,fit,zoom,next,ax,ay,bx,by);check(Math.abs((bx-p[0])/(fit*next)-wx)<.04,"pinch and pan preserve world X anchor");check(Math.abs((by-p[1])/(fit*next)-wy)<.04,"pinch and pan preserve world Y anchor");float[] same=CanvasViewport.zoom(tx,ty,fit,zoom,zoom,ax,ay,bx,by);check(Math.abs(same[0]-tx-100)<.02&&Math.abs(same[1]-ty+75)<.02,"same-scale midpoint motion is pure translation");}
        for(float scale:new float[]{.000001f,.00001f,.0001f,.001f,.02f,.08f,.3f,1,3,12,36})for(int size:new int[]{400,1200,3000,8000}){float width=size/scale,height=size*.73f/scale,unit=CanvasViewport.levelScale(CanvasViewport.level(scale,width,height));check(Math.max(width,height)*unit<=5100,"tile level bounds pixel memory independently of world extent");if(size<=3000)check(unit>=scale*.9999f&&unit<=scale*1.415f,"tablet raster retains at least screen resolution");for(int i=0;i<100;i++){float x=(random.nextFloat()-.5f)*1000000,y=(random.nextFloat()-.5f)*1000000,side=512/unit;int n=((int)Math.floor((x+width)/side)-(int)Math.floor(x/side)+1)*((int)Math.floor((y+height)/side)-(int)Math.floor(y/side)+1);check(n<=192,"visible tile set fits LRU capacity");}float grid=CanvasViewport.gridStep(32,scale,true);check(grid*scale>=12&&grid>=32,"zoomed-out dots remain sparse");}check(CanvasViewport.key(-1,0)!=CanvasViewport.key(0,-1),"negative tile coordinates have distinct keys");System.out.println("PASS pinch anchor, simultaneous pan, bounded visible tile working set, sparse grid and negative tile keys");}
    static void export(){Ink.Page page=new Ink.Page();page.strokes.add(line(-30000,-40000,-29000,-39700));page.strokes.add(line(50000,60000,50100,60200));float[] b=CanvasViewport.exportBounds(page);for(Ink.Stroke s:page.strokes){float[] bounds=s.bounds();check(b[0]<=bounds[0]&&b[1]<=bounds[1]&&b[2]>=bounds[2]&&b[3]>=bounds[3],"full canvas export contains far and negative ink");}check(b[2]-b[0]>80000&&b[3]-b[1]>100000,"export is independent of nominal page size");page.hasViewport=true;page.viewX=-30000;page.viewY=60000;page.viewZoom=2;Ink.Page copy=page.copy();check(copy.infinite&&copy.hasViewport&&copy.viewX==page.viewX&&copy.viewY==page.viewY&&copy.viewZoom==2,"snapshot retains plane mode and viewport");page.background="sample.png";b=CanvasViewport.exportBounds(page);check(b[0]<0&&b[1]<0&&b[2]>page.width&&b[3]>page.height,"expanded PDF export contains background and outside ink");page.infinite=false;b=CanvasViewport.exportBounds(page);check(b[0]==0&&b[1]==0&&b[2]==1200&&b[3]==1640,"finite PDF page keeps original crop");page=new Ink.Page();b=CanvasViewport.exportBounds(page);check(b[2]>b[0]&&b[3]>b[1],"empty canvas has a valid export");page.strokes.add(line(-3,4,-3,4));b=CanvasViewport.exportBounds(page);check(b[2]-b[0]>=320&&b[3]-b[1]>=240,"single point does not create zero-size bitmap");System.out.println("PASS full content export bounds, outside ink, page snapshots, expanded PDF and finite/empty/tiny export");}
    static void broadIndex(){SpatialIndex index=new SpatialIndex();ArrayList<Ink.Stroke> all=new ArrayList<>();for(int i=0;i<10000;i++){float x=(i%100)*50000-2500000,y=(i/100)*50000-2500000;Ink.Stroke s=line(x,y,x+40,y+50);all.add(s);index.add(s,i);}for(int i=0;i<80;i++){float l=(random.nextInt(100)*50000)-2500500,t=(random.nextInt(100)*50000)-2500500,r=l+30000,b=t+30000;ArrayList<Ink.Stroke> expected=new ArrayList<>();for(Ink.Stroke s:all)if(CanvasViewport.overlaps(s.bounds(),l,t,r,b))expected.add(s);check(index.query(l,t,r,b).equals(expected),"broad zoom keeps exact order and strokes");check(index.lastCandidates<20,"broad sparse query does not scan the notebook");}Ink.Stroke enormous=line(-3e38f,-3e38f,3e38f,3e38f);index.add(enormous,10001);check(index.large.contains(enormous)&&index.coarseLarge.contains(enormous),"coordinate overflow cannot expand the sparse grid");check(index.query(-1,-1,1,1).contains(enormous),"enormous stroke remains visible");index.clear();check(index.coarseCells.isEmpty()&&index.coarseLarge.isEmpty(),"coarse index is cleared");System.out.println("PASS broad overview queries use sparse coarse cells without losing strokes");}
    public static void main(String[] args){index();broadIndex();viewport();export();System.out.println("PASS: "+assertions+" infinite canvas assertions");}
}
